'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { 
  FaExclamationTriangle,
  FaCalendarAlt,
  FaChevronRight
} from 'react-icons/fa';
import { fetSessionInfo, fetchTasks, fetchEvents, filterEventsByDate } from '@/lib/planner';

export default function ProfileSidebar() {
  const [tasksReminder, setTasksReminder] = useState<any[]>([]);
  const [eventsTomorrow, setEventsTomorrow] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchPlannerData = async () => {
      try {
        setIsLoading(true);
        const { user, accessToken } = await fetSessionInfo();
        const [tasks, events] = await Promise.all([
          fetchTasks(user.id, accessToken),
          fetchEvents(user.id, accessToken),
        ]);

        const highPriorityTasks = tasks.filter(
          (task: any) => task.priority === 'HIGH' && task.status !== 'Done'
        );
        
        const tomorrow = new Date();
        tomorrow.setDate(tomorrow.getDate() + 1);
        const tomorrowEvents = filterEventsByDate(events, tomorrow);

        setTasksReminder(highPriorityTasks);
        setEventsTomorrow(tomorrowEvents);
      } catch (err) {
        console.error(err);
      } finally {
        setIsLoading(false);
      }
    };

    fetchPlannerData();
  }, []);

  return (
    <aside className="fixed top-6 -right-4 h-[calc(100vh-2rem)] w-60 bg-white rounded-xl shadow-md p-6 hidden md:block overflow-y-auto">
      <h2 className="text-lg font-semibold text-gray-800 mb-6">Today's Overview</h2>

      <div className="space-y-6">
        {isLoading ? (
          <div className="flex justify-center items-center h-40">
            <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-blue-500"></div>
          </div>
        ) : (
          <>
            <div>
              <h4 className="font-semibold text-sm text-red-700 flex items-center gap-2">
                <FaExclamationTriangle /> Urgent Tasks
              </h4>
              {tasksReminder.length > 0 ? (
                <ul className="text-sm text-gray-800 mt-2 space-y-2">
                  {tasksReminder.slice(0, 3).map(task => (
                    <li key={task.id} className="flex items-start">
                      <span className="mr-2">•</span>
                      <div>
                        <span>{task.title}</span>
                        {task.dueDate && (
                          <span className="text-xs text-gray-500 block">
                            Due: {new Date(task.dueDate).toLocaleDateString()}
                          </span>
                        )}
                      </div>
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="text-sm text-gray-500 mt-2">No urgent tasks</p>
              )}
            </div>

            <div>
              <h4 className="font-semibold text-sm text-blue-700 flex items-center gap-2">
                <FaCalendarAlt /> Tomorrow's Events
              </h4>
              {eventsTomorrow.length > 0 ? (
                <ul className="text-sm text-gray-800 mt-2 space-y-2">
                  {eventsTomorrow.map(event => (
                    <li key={event.id} className="flex items-start">
                      <span className="mr-2">•</span>
                      <div>
                        <span>{event.title}</span>
                        <span className="text-xs text-gray-500 block">
                          {new Date(event.startTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                          {event.location && ` • ${event.location}`}
                        </span>
                      </div>
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="text-sm text-gray-500 mt-2">No events scheduled</p>
              )}
            </div>

            <Link
              href="/planner"
              className="flex items-center justify-between mt-4 text-sm text-blue-600 hover:text-blue-800 font-medium p-2 hover:bg-blue-50 rounded-lg transition-colors"
            >
              <span>Go to Planner</span>
              <FaChevronRight className="text-xs" />
            </Link>
          </>
        )}
      </div>
    </aside>
  );
}